    $add.add_Click(({ $c=Get-InventoryAdminCode $allGrid;if($c-and-not($ctx.Clothing-contains$c)){if($ctx.Clothing.Count-ge256){[Windows.Forms.MessageBox]::Show('The maximum limit for the suitcase is256Seed。')|Out-Null;return};[void]$ctx.Clothing.Add($c);&$refreshClothing}}).GetNewClosure());$del.add_Click(({ $c=Get-InventoryAdminCode $ownedGrid;if($c){[void]$ctx.Clothing.Remove($c);&$refreshClothing}}).GetNewClosure());$allGrid.add_CellDoubleClick(({param($s,$e)$add.PerformClick()}).GetNewClosure())

