    $ps1=New-Object Windows.Forms.TextBox;$ps1.Location='10,30';$ps1.Size='280,25';$petTab.Controls.Add($ps1);$ps2=New-Object Windows.Forms.TextBox;$ps2.Location='375,30';$ps2.Size='280,25';$petTab.Controls.Add($ps2);$gs=New-Object Windows.Forms.TextBox;$gs.Location='740,30';$gs.Size='280,25';$petTab.Controls.Add($gs)
    $pg1=New-InventoryAdminGrid $petTab 10 62 340 463;$pg2=New-InventoryAdminGrid $petTab 375 62 340 463;$gg=New-InventoryAdminGrid $petTab 740 62 340 463
    $pt1=New-InventoryAdminTable @('Name','ID','Base attack','Effective attack','HPAdd','MPAdd','Slot','Gems1','Gems2','Gems3');$pv1=New-Object Data.DataView;$pv1.Table=$pt1;$pg1.DataSource=$pv1;$pt2=New-InventoryAdminTable @('Name','ID','Base attack','Slot','Level Requirements');foreach($x in $catalog.pets){[void]$pt2.Rows.Add($x.name,[string]$x.id,[string]$x.base_attack,[string]$x.slot_count,[string]$x.level_requirement)};$pv2=New-Object Data.DataView;$pv2.Table=$pt2;$pg2.DataSource=$pv2;$gt=New-InventoryAdminTable @('Name','ID','Effects','Attack','Attack%','HP','MP');foreach($x in $catalog.gems){[void]$gt.Rows.Add($x.name,[string]$x.id,$x.effect,[string]$x.attack_flat,[string]$x.attack_percent,[string]$x.hp,[string]$x.mp)};$gv=New-Object Data.DataView;$gv.Table=$gt;$gg.DataSource=$gv
