    $petAdd=New-Object Windows.Forms.Button;$petAdd.Text='Add the middle pet to the left column';$petAdd.Location='375,535';$petAdd.Size='200,34';$petTab.Controls.Add($petAdd);$petDel=New-Object Windows.Forms.Button;$petDel.Text='Remove left row selected pet';$petDel.Location='15,535';$petDel.Size='210,34';$petDel.BackColor=[Drawing.Color]::MistyRose;$petTab.Controls.Add($petDel);$upgrade=New-Object Windows.Forms.CheckBox;$upgrade.Text='Gold powder upgrade';$upgrade.Location='15,578';$upgrade.Size='130,28';$petTab.Controls.Add($upgrade)
