    $updatePetDetail={ $c=Get-InventoryAdminCode $pg1;if(-not$c){$petDetail.Text='Select the existing pet to view the properties and edit the gems。';return};$r=&$getPetRow $c;$p=$byPet[$c];$upgrade.Checked=([uint32]$r.upgrade_material-ne0);$petDetail.Text="$($p.name) [$c]  Base attack=$($p.base_attack)，Slot=$($p.slot_count)，Age Dollardata=$($p.display_age)/$($p.max_age)，Level Requirements=$($p.level_requirement)，Upgrade material=$($p.upgrade_material)" }.GetNewClosure();$pg1.add_SelectionChanged($updatePetDetail);&$updatePetDetail
    $ps1.add_TextChanged(({Set-InventoryAdminFilter $pv1 $ps1.Text @('Name','ID','Gems1','Gems2','Gems3')}).GetNewClosure());$ps2.add_TextChanged(({Set-InventoryAdminFilter $pv2 $ps2.Text @('Name','ID','Base attack','Level Requirements')}).GetNewClosure());$gs.add_TextChanged(({Set-InventoryAdminFilter $gv $gs.Text @('Name','ID','Effects','Attack','Attack%','HP','MP')}).GetNewClosure())
