    # Game items
    $gameTab=New-Object Windows.Forms.TabPage;$gameTab.Text='Game prop management';$Tabs.TabPages.Add($gameTab);$gos=New-Object Windows.Forms.TextBox;$gos.Location='15,15';$gos.Size='350,26';$gameTab.Controls.Add($gos);$gas=New-Object Windows.Forms.TextBox;$gas.Location='555,15';$gas.Size='350,26';$gameTab.Controls.Add($gas);$gog=New-InventoryAdminGrid $gameTab 15 50 430 650;$gag=New-InventoryAdminGrid $gameTab 555 50 525 650
    $got=New-InventoryAdminTable @('Name','ID','Number','Carrier','Classification');$gov=New-Object Data.DataView;$gov.Table=$got;$gog.DataSource=$gov;$gat=New-InventoryAdminTable @('Name','ID','Carrier','Classification','Annotations','Effects');foreach($x in $catalog.game){[void]$gat.Rows.Add($x.name,[string]$x.id,$x.carrier,$x.category,$x.description,$x.effect)};$gav=New-Object Data.DataView;$gav.Table=$gat;$gag.DataSource=$gav
    $refreshGame={ $got.Rows.Clear();foreach($r in $ctx.GameItems){$x=$byGame[[uint32]$r.code];[void]$got.Rows.Add($(if($x){$x.name}else{"ITEM-$($r.code)"}),[string]$r.code,[string]$r.count,$r.carrier,$(if($x){$x.category}else{''}))} }.GetNewClosure();&$refreshGame
    $qty=New-Object Windows.Forms.NumericUpDown;$qty.Minimum=1;$qty.Maximum=255;$qty.Value=1;$qty.Location='465,235';$qty.Size='75,28';$gameTab.Controls.Add($qty);$ga=New-Object Windows.Forms.Button;$ga.Text='← Increase';$ga.Location='460,275';$ga.Size='80,34';$gameTab.Controls.Add($ga);$gd=New-Object Windows.Forms.Button;$gd.Text='Reduction/Delete →';$gd.Location='450,325';$gd.Size='95,34';$gameTab.Controls.Add($gd)
