    $ga.add_Click(({ $c=Get-InventoryAdminCode $gag;if(-not$c){return};$carrier=[string]$gag.CurrentRow.Cells['Carrier'].Value;$r=@($ctx.GameItems|Where-Object{$_.code-eq$c-and$_.carrier-eq$carrier})[0];if($r){$r.count=[math]::Min(255,[int]$r.count+[int]$qty.Value)}else{[void]$ctx.GameItems.Add([pscustomobject]@{code=$c;count=[uint32]$qty.Value;carrier=$carrier})};&$refreshGame}).GetNewClosure());$gd.add_Click(({ $c=Get-InventoryAdminCode $gog;if(-not$c){return};$carrier=[string]$gog.CurrentRow.Cells['Carrier'].Value;$r=@($ctx.GameItems|Where-Object{$_.code-eq$c-and$_.carrier-eq$carrier})[0];if($r){$r.count=[int]$r.count-[int]$qty.Value;if($r.count-le0){[void]$ctx.GameItems.Remove($r)};&$refreshGame}}).GetNewClosure())

