    $fot=New-InventoryAdminTable @('Name','ID','Examples','Type','Its set','X','Y');$fov=New-Object Data.DataView;$fov.Table=$fot;$fog.DataSource=$fov;$fat=New-InventoryAdminTable @('Name','ID','Type','Duration','Gold','NANA','Annotations');foreach($x in $catalog.furniture){[void]$fat.Rows.Add($x.name,[string]$x.id,$x.type_name,[string]$x.days,[string]$x.coin,[string]$x.nana,$x.description)};$fav=New-Object Data.DataView;$fav.Table=$fat;$fag.DataSource=$fav
    $refreshFurniture={ $fot.Rows.Clear();foreach($r in $ctx.Furniture){$x=$byFurniture[[uint32]$r.code];[void]$fot.Rows.Add($(if($x){$x.name}else{"FURNITURE-$($r.code)"}),[string]$r.code,[string]$r.index,$(if($x){$x.type_name}else{$r.type}),$(if($r.placed){'Yes'}else{'No'}),[string]$r.x,[string]$r.y)} }.GetNewClosure();&$refreshFurniture
    $fa=New-Object Windows.Forms.Button;$fa.Text='← Add instance';$fa.Location='450,275';$fa.Size='95,35';$fTab.Controls.Add($fa);$fd=New-Object Windows.Forms.Button;$fd.Text='Remove instance →';$fd.Location='450,325';$fd.Size='95,35';$fTab.Controls.Add($fd);$fos.add_TextChanged(({Set-InventoryAdminFilter $fov $fos.Text @('Name','ID','Examples','Type','Its set')}).GetNewClosure());$fas.add_TextChanged(({Set-InventoryAdminFilter $fav $fas.Text @('Name','ID','Type','Annotations')}).GetNewClosure())
    $fa.add_Click(({ $c=Get-InventoryAdminCode $fag;if(-not$c){return};if($ctx.Furniture.Count-ge254){[Windows.Forms.MessageBox]::Show('The ceiling for the furniture instance is254。')|Out-Null;return};$used=@($ctx.Furniture|ForEach-Object{[int]$_.index});$idx=1;while($used-contains$idx){$idx++};$x=$byFurniture[$c];[void]$ctx.Furniture.Add([pscustomobject]@{code=$c;index=$idx;placed=$false;type=[byte]$x.type;x=400;y=300;z=0;mirror=0});&$refreshFurniture}).GetNewClosure());$fd.add_Click(({ if(-not$fog.CurrentRow){return};$idx=[int]$fog.CurrentRow.Cells['Examples'].Value;$r=@($ctx.Furniture|Where-Object{$_.index-eq$idx})[0];if($r){[void]$ctx.Furniture.Remove($r);&$refreshFurniture}}).GetNewClosure())

    # Cards
    $cTab=New-Object Windows.Forms.TabPage;$cTab.Text='Card Management';$Tabs.TabPages.Add($cTab);$cos=New-Object Windows.Forms.TextBox;$cos.Location='15,15';$cos.Size='350,26';$cTab.Controls.Add($cos);$cas=New-Object Windows.Forms.TextBox;$cas.Location='555,15';$cas.Size='350,26';$cTab.Controls.Add($cas);$cog=New-InventoryAdminGrid $cTab 15 50 430 650;$cag=New-InventoryAdminGrid $cTab 555 50 525 650
    $cot=New-InventoryAdminTable @('Name','ID','Number');$cov=New-Object Data.DataView;$cov.Table=$cot;$cog.DataSource=$cov;$cat=New-InventoryAdminTable @('Name','ID','Annotations','Effects','Products');foreach($x in $catalog.cards){[void]$cat.Rows.Add($x.name,[string]$x.id,$x.description,$x.effect,$x.result)};$cav=New-Object Data.DataView;$cav.Table=$cat;$cag.DataSource=$cav
